?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>AI Training Health</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>.th-grid{display:grid;grid-template-columns:.72fr 1.28fr;gap:14px;margin-top:14px}.th-card{padding:18px;border:1px solid #dce7e0;border-radius:17px;background:#fff}.th-score{display:grid;place-items:center;width:150px;height:150px;margin:10px auto;border-radius:50%;background:conic-gradient(#16804c calc(var(--score)*1%),#e5eee8 0);position:relative}.th-score:after{content:'';position:absolute;width:116px;height:116px;border-radius:50%;background:#fff}.th-score strong{position:relative;z-index:1;font-size:2rem}.th-check{display:flex;align-items:center;justify-content:space-between;padding:11px 0;border-bottom:1px solid #e6ede9}.th-check span:last-child{padding:5px 8px;border-radius:999px;background:#eaf7ef;color:#176b42;font-size:.64rem;font-weight:850}.th-check.bad span:last-child{background:#fff1ed;color:#a34535}.th-alert{padding:13px;border-radius:12px;background:#fff7e9;color:#7a5720}.th-good{background:#edf9f1;color:#17633d}.th-form{display:grid;gap:9px;margin-top:12px}.th-form input,.th-form textarea{border:1px solid #d6e2da;border-radius:10px;padding:10px}.th-form button{border:0;border-radius:10px;background:#167548;color:#fff;padding:11px;font-weight:850}.th-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:12px}.th-stat{padding:12px;border:1px solid #e0e9e4;border-radius:12px;background:#fbfdfc}.th-stat b,.th-stat small{display:block}.th-stat b{font-size:1.25rem}.th-stat small{color:#6a7d72}@media(max-width:850px){.th-grid{grid-template-columns:1fr}}@media(max-width:550px){.th-stats{grid-template-columns:1fr}}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>AI Training Health</small></span></a><div class="os-top-actions"><a class="os-btn" href="ai_improvement_dashboard.php">Analytics</a><a class="os-btn" href="ai_knowledge_manager.php">Knowledge Manager</a><a class="os-btn primary" href="customer_site_manager.php">Site Manager</a></div></div></header><main class="os-main" style="max-width:1400px;margin:auto"><section class="os-hero"><div class="os-kicker">KNOWLEDGE QUALITY & RETRAINING</div><h1>Know exactly when the AI is ready to retrain.</h1><p>Health checks combine configuration, verified knowledge, unanswered backlog and the last recorded Chatbase retraining fingerprint.</p></section><?php if($error):?><div class="pp-alert bad" style="margin-top:14px"><?=ath($error)?></div><?php endif;?><?php if($success):?><div class="pp-alert good" style="margin-top:14px"><?=ath($success)?></div><?php endif;?><section class="th-grid"><article class="th-card"><h2>Training Health Score</h2><div class="th-score" style="--score:<?=(int)($health['score']??0)?>"><strong><?=(int)($health['score']??0)?>%</strong></div><div class="th-stats"><div class="th-stat"><b><?=(int)($health['verified_answers']??0)?></b><small>Verified answers</small></div><div class="th-stat"><b><?=(int)($health['open_questions']??0)?></b><small>Open questions</small></div><div class="th-stat"><b><?=ath((string)($health['last_retrained_at']?:'Never'))?></b><small>Last retrained</small></div></div></article><article class="th-card"><h2>Readiness Checks</h2><?php foreach($health['checks']??[] as $key=>$ok):?><div class="th-check <?=$ok?'':'bad'?>"><span><?=ath($labels[$key]??$key)?></span><span><?=$ok?'READY':'ACTION NEEDED'?></span></div><?php endforeach;?><div class="th-alert <?=empty($health['retraining_needed'])?'th-good':''?>" style="margin-top:13px"><b><?=!empty($health['retraining_needed'])?'Retraining recommended':'Training is current'?></b><div><?=!empty($health['retraining_needed'])?'Verified website knowledge changed after the last recorded Chatbase training.':'The saved Chatbase training fingerprint matches current verified knowledge.'?></div></div><form method="post" class="th-form"><input type="hidden" name="csrf" value="<?=ath($csrf)?>"><input name="source_url" placeholder="Online HTTPS crawler feed URL"><textarea name="notes" maxlength="2000" placeholder="Optional retraining notes"></textarea><button type="submit">Mark Current Knowledge as Retrained</button></form><p style="font-size:.68rem;color:#6b7d73">Use this button only after retraining finishes in Chatbase. It records evidence; it does not call Chatbase automatically.</p></article></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
